        A[i], A[max_row] = A[max_row], A[i]

        # Eliminate below the pivot
        factor = Fraction(A[i][i])
        for j in range(i, n):
            A[i][j] /= factor

        for k in range(i+1, n):
            factor = Fraction(A[k][i])
            for j in range(i, n):
                A[k][j] -= factor * A[i][j]

    # Back-substitute to get the rank
